/**
 * Wire protocol for the ephemeral chat rooms.
 *
 * This package is the single source of truth for both the backend (which
 * validates frames with the Zod schemas in `@chat/protocol/schemas`) and the
 * frontend (which only needs the constants and types).
 *
 * Invariants:
 * - The server is the only source of truth for `sender`, `timestamp` and `id`.
 * - Every room id is a 128-bit capability generated by the server (22 chars base64url).
 * - Nothing in this protocol is persisted; a room only exists while it is in memory.
 */

export const LIMITS = {
  usernameMaxLength: 32,
  messageMaxLength: 4096,
  roomIdMinLength: 16,
  roomIdMaxLength: 64,
} as const

/** Convenience aliases used by the client UI. */
export const MAX_USERNAME_LENGTH = LIMITS.usernameMaxLength
export const MAX_MESSAGE_LENGTH = LIMITS.messageMaxLength
export const ROOM_ID_MIN_LENGTH = LIMITS.roomIdMinLength
export const ROOM_ID_MAX_LENGTH = LIMITS.roomIdMaxLength

export const ROOM_ID_PATTERN = /^[A-Za-z0-9_-]+$/

/** WebSocket close codes that both sides reason about. */
export const CLOSE_CODES = {
  roomExpired: 4001,
  rateLimited: 4008,
} as const

export function isValidRoomId(value: string): boolean {
  return (
    value.length >= ROOM_ID_MIN_LENGTH &&
    value.length <= ROOM_ID_MAX_LENGTH &&
    ROOM_ID_PATTERN.test(value)
  )
}

export type ErrorCode =
  | "invalid_payload"
  | "room_not_found"
  | "room_full"
  | "username_taken"
  | "already_joined"
  | "not_a_member"
  | "too_many_rooms"
  | "rate_limited"
  | "server_error"

export interface ChatMessage {
  id: string
  type: "chat"
  sender: string
  message: string
  timestamp: number
}

export interface SystemMessage {
  id: string
  type: "system"
  sender: "system"
  message: string
  timestamp: number
}

export type RoomMessage = ChatMessage | SystemMessage

export interface RoomSnapshot {
  roomId: string
  /** Server-authoritative expiry timestamp (ms). Clients only render this. */
  expiresAt: number
  ttlMs: number
  /** Only chat messages are retained; system messages are live-only. */
  history: ChatMessage[]
  users: string[]
}

export interface ReadyMessage extends RoomSnapshot {
  type: "ready"
}

export type ServerMessage =
  | ReadyMessage
  | ChatMessage
  | SystemMessage
  | { type: "presence"; users: string[]; expiresAt?: number }
  | { type: "expired" }
  | { type: "error"; code: ErrorCode; message: string }

export type ClientMessage =
  | { type: "create"; username: string }
  | { type: "join"; roomId: string; username: string }
  | { type: "chat"; message: string }

export type ParseClientMessageResult =
  | { ok: true; value: ClientMessage }
  | { ok: false; message: string }
